41	// loginHintErr maps auth.ErrNotLoggedIn to the standard login hint; other
42	// errors pass through unchanged.
43	func loginHintErr(err error) error {
44		if errors.Is(err, auth.ErrNotLoggedIn) {
45			return errors.New("not authenticated. Run 'entire login' to authenticate")
46		}
47		return err
48	}
