50	// semanticSearchV4Session holds per-invocation state for the v4 query-serve
51	// path. Control-plane discovery (the repo index, per-slug repo lookups, the
52	// cluster catalog) is stable for the life of one command, so it is resolved
53	// once and reused across TUI re-searches and pagination instead of paying
54	// several network round trips per keystroke-search. Identity tokens are NOT
55	// cached here — fanOutCells mints them per search (at most one per
56	// jurisdiction), which keeps expiry handling in the auth layer.
57	type semanticSearchV4Session struct {
58		insecureHTTP bool
59	
60		mu         sync.Mutex
61		coreClient *coreapi.Client
62		clusters   *cachedClusterClient
63		fullIndex  *coreapi.ListReposOutputBody        // unfiltered index, fetched at most once
64		slugRepos  map[string][]coreapi.RepoIndexEntry // per-filter exact-match lookups
65	}
66	
67	// search performs a v4 query-serve search across every cell that hosts the
68	// caller's in-scope repos, then merges the per-cell responses into one
69	// response. It is the semantic sibling of searchAllCells (code): resolve
70	// scope → group by hosting cell → one query-serve call per cell → tiered
71	// merge.
72	//
73	// Scope follows Config.ScopeSlugs — an explicit repo filter wins over
74	// --all-repos (the more specific filter scopes the search):
75	//   - unfiltered (repo:* / --all-repos with no explicit filter) → every cell
76	//     is queried with NO repo param, so query-serve returns everything the
77	//     caller's token authorizes there (matching the BFF and keeping the query
78	//     small for users with many repos).
79	//   - explicit repo filter(s) or the current-repo default → the slugs are
80	//     resolved via truncation-proof exact-match lookups and each cell is
81	//     scoped to the ULIDs it hosts.
82	//
83	// Completeness caveats (truncated index, failed regions) are returned as
84	// Response.Warnings for the caller to surface.
85	func (s *semanticSearchV4Session) search(ctx context.Context, cfg search.Config) (*search.Response, error) {
86		if err := search.ValidateRepoFilters(cfg.Repos); err != nil {
87			return nil, err //nolint:wrapcheck // user-facing validation message
88		}
89	
90		coreClient, err := s.client()
91		if err != nil {
92			if errors.Is(err, auth.ErrNotLoggedIn) {
93				return nil, loginHintErr(err)
94			}
95			return nil, fmt.Errorf("semantic search: resolving control-plane client: %w", err)
96		}
97	
98		slugs, allRepos := cfg.ScopeSlugs()
99		var cells []cellGroup
100		var warnings []string
101		scoped := !allRepos
102		if scoped {
103			if len(slugs) == 0 {
104				return nil, errors.New("semantic search: could not determine the repository to search")
105			}
106			entries, err := s.resolveScope(ctx, slugs)
107			if err != nil {
108				return nil, err
109			}
110			cells = groupReposByCell(entries)
111		} else {
112			index, err := s.listFullIndex(ctx)
113			if err != nil {
114				return nil, fmt.Errorf("semantic search: listing repos for cell discovery: %w", err)
115			}
116			if index.Truncated {
117				// Debug, not Warn: the user-facing channel is the Warnings entry;
118				// slog's default handler would print a Warn straight to stderr on
119				// commands that never ran logging.Init.
120				logging.Debug(ctx, "semantic search: repo index truncated; cross-repo results may be incomplete")
121				warnings = append(warnings, "repo index truncated; cross-repo results may be incomplete")
122			}
123			cells = groupReposByCell(index.Repos)
124		}
125	
126		if len(cells) == 0 {
127			return &search.Response{Results: []search.Result{}, Page: 1, Warnings: warnings}, nil
128		}
129		resolveCellBaseURLs(ctx, s.clusterClient(coreClient), cells)
130	
131		results, err := fanOutCells(ctx, s.insecureHTTP, semanticSearchV4CellTimeout, cells, func(ctx context.Context, group cellGroup, client *api.Client) (*search.Response, error) {
132			// Scoped: restrict the cell to the ULIDs it hosts. Unfiltered: send no
133			// repo param and let query-serve search everything the token
134			// authorizes in that cell (avoids per-request repo-filter caps for
135			// large accounts).
136			var repoIDs []string
137			if scoped {
138				repoIDs = group.repoIDs
139			}
140			return search.CellV4(ctx, client, cfg, repoIDs)
141		})
142		if err != nil {
143			if errors.Is(err, auth.ErrNotLoggedIn) {
144				return nil, loginHintErr(err)
145			}
146			return nil, fmt.Errorf("semantic search: %w", err)
147		}
148	
149		resp, err := mergeSemanticV4Responses(ctx, cfg.Limit, cfg.Page, results)
150		if err != nil {
151			return nil, err
152		}
153		resp.Warnings = append(warnings, resp.Warnings...)
154		return resp, nil
155	}
