172	// listFullIndex fetches (once) and caches the caller's full repo index, used
173	// for unfiltered searches and raw-ID filter matching.
174	func (s *semanticSearchV4Session) listFullIndex(ctx context.Context) (*coreapi.ListReposOutputBody, error) {
175		s.mu.Lock()
176		defer s.mu.Unlock()
177		if s.fullIndex != nil {
178			return s.fullIndex, nil
179		}
180		reposCtx, cancel := context.WithTimeout(ctx, semanticSearchControlPlaneTimeout)
181		defer cancel()
182		index, err := s.coreClient.ListRepos(reposCtx, coreapi.ListReposParams{})
183		if err != nil {
184			return nil, err
185		}
186		s.fullIndex = index
187		return index, nil
188	}
189	
190	// resolveScope resolves explicit repo filters (or the current-repo default)
191	// to index entries, deduped by repo ID. owner/name slugs use the exact-match
192	// ListRepos filter — immune to index truncation on large accounts — while raw
193	// IDs (no slash) fall back to matching against the full index. Zero matches
194	// is a clear error; a partially matched multi-repo filter proceeds with the
195	// matches, like resolveRepoFilters does for code search.
196	func (s *semanticSearchV4Session) resolveScope(ctx context.Context, slugs []string) ([]coreapi.RepoIndexEntry, error) {
197		var entries []coreapi.RepoIndexEntry
198		seen := make(map[string]bool, len(slugs))
199		for _, f := range slugs {
200			matched, err := s.lookupFilter(ctx, f)
201			if err != nil {
202				return nil, err
203			}
204			for _, e := range matched {
205				if !seen[e.ID] {
206					seen[e.ID] = true
207					entries = append(entries, e)
208				}
209			}
210		}
211		if len(entries) == 0 {
212			return nil, fmt.Errorf("no matching repositories found for %v (is the repo mirrored to Entire?)", slugs)
213		}
214		return entries, nil
215	}
216	
217	// lookupFilter resolves one repo filter to index entries, cached per session.
218	// Matching mirrors resolveRepoFilters: a gh/ prefix is stripped, owner/name
219	// matches full_name (case-insensitive, server-side exact match), and a raw
220	// ULID matches the index entry's ID.
221	func (s *semanticSearchV4Session) lookupFilter(ctx context.Context, filter string) ([]coreapi.RepoIndexEntry, error) {
222		s.mu.Lock()
223		if cached, ok := s.slugRepos[filter]; ok {
224			s.mu.Unlock()
225			return cached, nil
226		}
227		s.mu.Unlock()
228	
229		slug := strings.TrimPrefix(filter, "gh/")
230		var matched []coreapi.RepoIndexEntry
231		if strings.Contains(slug, "/") {
232			lookupCtx, cancel := context.WithTimeout(ctx, semanticSearchControlPlaneTimeout)
233			defer cancel()
234			out, err := s.coreClient.ListRepos(lookupCtx, coreapi.ListReposParams{Filter: coreapi.NewOptString(slug)})
235			if err != nil {
236				return nil, fmt.Errorf("semantic search: resolving repository %q: %w", filter, err)
237			}
238			matched = out.Repos
239		} else {
240			// Raw repo ID — the exact-match filter only matches full_name, so
241			// match by ID against the full index.
242			index, err := s.listFullIndex(ctx)
243			if err != nil {
244				return nil, fmt.Errorf("semantic search: resolving repository %q: %w", filter, err)
245			}
246			_, matched = resolveRepoFilters([]string{filter}, index.Repos)
247		}
248	
249		s.mu.Lock()
250		if s.slugRepos == nil {
251			s.slugRepos = make(map[string][]coreapi.RepoIndexEntry)
252		}
253		s.slugRepos[filter] = matched
254		s.mu.Unlock()
255		return matched, nil
256	}
