301	// mergedTier2Max mirrors query-serve's maxTier2 and the BFF's MERGED_TIER2_MAX:
302	// the ANN-only fallback tail is capped when it's all there is.
303	const mergedTier2Max = 15
304	
305	// tierOf returns a result's tier, or -1 when unset (treated as the ANN-only
306	// fallback tier).
307	func tierOf(r search.Result) int {
308		if r.Meta.Tier == nil {
309			return -1
310		}
311		return *r.Meta.Tier
312	}
313	
314	func bm25Of(r search.Result) float64 {
315		if r.Meta.BM25Score != nil {
316			return *r.Meta.BM25Score
317		}
318		return 0
319	}
320	
321	// annOrScoreOf prefers the raw ANN score, falling back to the overall score —
322	// the ordering key query-serve/BFF use for the tier-2 ANN fallback (for
323	// tier-2 rows Score is itself ANN-derived, so lower is better in both cases).
324	func annOrScoreOf(r search.Result) float64 {
325		if r.Meta.ANNScore != nil {
326			return *r.Meta.ANNScore
327		}
328		return r.Meta.Score
329	}
330	
331	// semanticCellPage is one cell's successful response plus the classification
332	// bit the merge keys on.
333	type semanticCellPage struct {
334		body     *search.Response
335		hasUpper bool // any non-repo tier-0/1 row
336	}
337	
338	// classifySemanticCells splits per-cell outcomes into successful pages, hard
339	// failures, and quietly-skipped cells. A cell is skipped — not failed — when
340	// it can't serve the search yet: its gateway has no query-serve route, or the
341	// cluster catalog doesn't expose the placement's jurisdiction at all (a cell
342	// mid-onboarding). Neither is worth warning the user about on every search.
343	func classifySemanticCells(ctx context.Context, results []cellCallResult[*search.Response]) (pages []semanticCellPage, failed []string, lastErr error) {
344		var skipped []string
345		for _, r := range results {
346			switch {
347			case errors.Is(r.err, search.ErrCellUnavailable), errors.Is(r.err, auth.ErrNoCellForJurisdiction):
348				skipped = append(skipped, r.group.label())
349			case r.err != nil:
350				lastErr = r.err
351				failed = append(failed, r.group.label())
352			case r.value != nil:
353				p := semanticCellPage{body: r.value}
354				for _, res := range r.value.Results {
355					// Repo rows never count as an upper tier — they're always
356					// merged regardless of the cell's checkpoint/commit tiers.
357					if res.Type != search.TypeRepo && (tierOf(res) == 0 || tierOf(res) == 1) {
358						p.hasUpper = true
359						break
360					}
361				}
362				pages = append(pages, p)
363			}
364		}
365		if len(skipped) > 0 {
366			logging.Debug(ctx, "semantic search: cells without query-serve skipped", "skipped_cells", skipped)
367		}
368		if len(pages) == 0 && lastErr == nil && len(skipped) > 0 {
369			lastErr = errNoRegionAvailable
370		}
371		return pages, failed, lastErr
372	}
373	
374	// errNoRegionAvailable is returned when every queried cell lacks query-serve.
375	var errNoRegionAvailable = errors.New("semantic search is not yet available in the region(s) hosting this search")
376	
377	// rankSemanticResults buckets every page's rows and applies the ordering
378	// query-serve uses within a cell (and the BFF uses across cells): repos first,
379	// then tier-0 by BM25 desc, tier-1 by rerank score desc, promoted tier-2 by
380	// ANN asc. Tier-2 rows arriving alongside tier 0/1 from the same cell were
381	// deliberately promoted by query-serve; a cell whose page is entirely tier 2
382	// had nothing better — its ANN fallback, shown (uncapped here) only when tiers
383	// 0/1 are empty everywhere.
384	func rankSemanticResults(pages []semanticCellPage) (merged []search.Result, globalUpper bool) {
385		for _, p := range pages {
386			if p.hasUpper {
387				globalUpper = true
388				break
389			}
390		}
391	
392		var repos, tier0, tier1, promotedTier2, fallbackTier2 []search.Result
393		for _, p := range pages {
394			for _, r := range p.body.Results {
395				switch {
396				case r.Type == search.TypeRepo:
397					repos = append(repos, r)
398				case tierOf(r) == 0:
399					tier0 = append(tier0, r)
400				case tierOf(r) == 1:
401					tier1 = append(tier1, r)
402				case p.hasUpper:
403					promotedTier2 = append(promotedTier2, r)
404				default:
405					fallbackTier2 = append(fallbackTier2, r)
406				}
407			}
408		}
409		sort.SliceStable(repos, func(i, j int) bool { return repos[i].Meta.Score > repos[j].Meta.Score })
410		merged = append(merged, repos...)
411		if globalUpper {
412			sort.SliceStable(tier0, func(i, j int) bool { return bm25Of(tier0[i]) > bm25Of(tier0[j]) })
413			sort.SliceStable(tier1, func(i, j int) bool { return tier1[i].Meta.Score > tier1[j].Meta.Score })
414			sort.SliceStable(promotedTier2, func(i, j int) bool { return annOrScoreOf(promotedTier2[i]) < annOrScoreOf(promotedTier2[j]) })
415			merged = append(merged, tier0...)
416			merged = append(merged, tier1...)
417			merged = append(merged, promotedTier2...)
418		} else {
419			sort.SliceStable(fallbackTier2, func(i, j int) bool { return annOrScoreOf(fallbackTier2[i]) < annOrScoreOf(fallbackTier2[j]) })
420			merged = append(merged, fallbackTier2...)
421		}
422		return merged, globalUpper
423	}
424	
425	// dedupSemanticResults removes cross-cell duplicates by type+id (a repo
426	// mirrored across cells returns the same logical result from each), keeping
427	// the first (higher-ranked) copy. Results without an id are always kept. The
428	// per-type dupe tally feeds the total/count corrections.
429	func dedupSemanticResults(merged []search.Result) ([]search.Result, map[string]int) {
430		seen := make(map[string]bool, len(merged))
431		dupesByType := make(map[string]int)
432		deduped := merged[:0]
433		for _, r := range merged {
434			id := r.ResultID()
435			if id == "" {
436				deduped = append(deduped, r)
437				continue
438			}
439			key := r.Type + "\x00" + id
440			if seen[key] {
441				dupesByType[r.Type]++
442				continue
443			}
444			seen[key] = true
445			deduped = append(deduped, r)
446		}
447		return deduped, dupesByType
448	}
449	
450	// aggregateSemanticTotals sums per-cell totals and counts, minus dedup, and
451	// excluding cells whose entire page was a discarded ANN fallback — their
452	// matches are unreachable, so they must not be advertised.
453	func aggregateSemanticTotals(pages []semanticCellPage, globalUpper bool, dupesByType map[string]int) (int, *search.TypeCounts) {
454		dupes := 0
455		for _, n := range dupesByType {
456			dupes += n
457		}
458		total := -dupes
459		counts := &search.TypeCounts{}
460		for _, p := range pages {
461			if globalUpper && !p.hasUpper {
462				// This page's non-repo rows were its ANN fallback and were
463				// dropped by the merge — those matches are unreachable, so only
464				// its repo rows (which are always merged) may be counted.
465				repoRows := 0
466				if p.body.Counts != nil {
467					repoRows = p.body.Counts.Repos
468				} else {
469					for _, r := range p.body.Results {
470						if r.Type == search.TypeRepo {
471							repoRows++
472						}
473					}
474				}
475				total += repoRows
476				counts.Repos += repoRows
477				continue
478			}
479			total += p.body.Total
480			if p.body.Counts != nil {
481				counts.Repos += p.body.Counts.Repos
482				counts.Checkpoints += p.body.Counts.Checkpoints
483				counts.Commits += p.body.Counts.Commits
484				counts.PRs += p.body.Counts.PRs
485				counts.Sessions += p.body.Counts.Sessions
486			}
487		}
488		subtractDupeCounts(counts, dupesByType)
489		return max(total, 0), counts
490	}
491	
492	// mergeSemanticV4Responses interleaves per-cell query-serve responses into one,
493	// applying the SAME ordering query-serve uses within a cell (see
494	// rankSemanticResults); when no cell produced tier 0/1 the ANN-only fallback
495	// tail is shown (deduped, then capped). Results are deduped by type+id and
496	// capped to limit. Rerank scores share a space across cells (same Cohere
497	// model), so interleaving is meaningful.
498	//
499	// Totals/counts include only cells whose results were actually mergeable (see
500	// aggregateSemanticTotals). All-cells-failed is an error; a partial failure is
501	// noted in Warnings and the surviving cells are merged.
502	func mergeSemanticV4Responses(ctx context.Context, limit, page int, results []cellCallResult[*search.Response]) (*search.Response, error) {
503		pages, failed, lastErr := classifySemanticCells(ctx, results)
504		if len(pages) == 0 {
505			if lastErr != nil {
506				return nil, fmt.Errorf("semantic search: %w", lastErr)
507			}
508			return &search.Response{Results: []search.Result{}, Page: 1}, nil
509		}
510		var warnings []string
511		if len(failed) > 0 {
512			// Debug, not Warn: the warning below already reaches the user via
513			// Response.Warnings, and slog's default handler would print a Warn
514			// straight to stderr on commands that never ran logging.Init.
515			logging.Debug(ctx, "semantic search: partial failure; results may be incomplete",
516				"succeeded", len(pages), "total", len(results), "failed_cells", failed)
517			warnings = append(warnings, fmt.Sprintf("search failed in %d of %d regions; results may be incomplete", len(failed), len(pages)+len(failed)))
518		}
519	
520		merged, globalUpper := rankSemanticResults(pages)
521		merged, dupesByType := dedupSemanticResults(merged)
522	
523		// Cap the ANN-only fallback tail AFTER dedup (repos always precede it),
524		// so cross-cell duplicates don't shrink the visible page below the cap.
525		if !globalUpper {
526			nRepos := 0
527			for _, r := range merged {
528				if r.Type != search.TypeRepo {
529					break
530				}
531				nRepos++
532			}
533			if len(merged) > nRepos+mergedTier2Max {
534				merged = merged[:nRepos+mergedTier2Max]
535			}
536		}
537		if limit > 0 && len(merged) > limit {
538			merged = merged[:limit]
539		}
540		if merged == nil {
541			merged = []search.Result{}
542		}
543	
544		total, counts := aggregateSemanticTotals(pages, globalUpper, dupesByType)
545		return &search.Response{
546			Results:  merged,
547			Total:    total,
548			Page:     max(page, 1),
549			Counts:   counts,
550			Warnings: warnings,
551		}, nil
552	}
553	
554	// subtractDupeCounts removes deduplicated rows from the aggregate per-type
555	// counts so `counts` reflects distinct results, matching the corrected total.
556	func subtractDupeCounts(counts *search.TypeCounts, dupesByType map[string]int) {
557		for typ, n := range dupesByType {
558			switch typ {
559			case search.TypeCheckpoint:
560				counts.Checkpoints = max(0, counts.Checkpoints-n)
561			case search.TypeCommit:
562				counts.Commits = max(0, counts.Commits-n)
563			case search.TypeSession:
564				counts.Sessions = max(0, counts.Sessions-n)
565			case search.TypeRepo:
566				counts.Repos = max(0, counts.Repos-n)
567			case search.TypePR:
568				counts.PRs = max(0, counts.PRs-n)
569			}
570		}
571	}
