138	// TestMergeSemanticV4Responses_ANNFallback verifies that when no cell produced
139	// tier 0/1 results, the ANN-only tail is shown, ordered ANN asc and capped at
140	// mergedTier2Max. Results without a tier field count as the fallback tier.
141	func TestMergeSemanticV4Responses_ANNFallback(t *testing.T) {
142		t.Parallel()
143	
144		var results []search.Result
145		for i := range mergedTier2Max + 5 {
146			results = append(results, v4Ckpt(
147				"c-"+string(rune('a'+i)), -1,
148				search.Meta{ANNScore: fptr(float64(i) / 100)},
149			))
150		}
151		resp, err := mergeSemanticV4Responses(context.Background(), 0, 0, []cellCallResult[*search.Response]{
152			v4CellOK(&search.Response{Results: results, Total: len(results)}),
153		})
154		if err != nil {
155			t.Fatal(err)
156		}
157		if len(resp.Results) != mergedTier2Max {
158			t.Errorf("fallback results = %d, want capped at %d", len(resp.Results), mergedTier2Max)
159		}
160		// ANN asc: the lowest scores survive the cap, in ascending order.
161		for i := 1; i < len(resp.Results); i++ {
162			if *resp.Results[i-1].Meta.ANNScore > *resp.Results[i].Meta.ANNScore {
163				t.Errorf("fallback not sorted ANN asc at %d", i)
164			}
165		}
166	}
