168	// TestMergeSemanticV4Responses_FallbackCapAfterDedup guards the cap ordering:
169	// cross-cell duplicates in the fallback tail must not shrink the visible page
170	// below mergedTier2Max when enough unique results exist.
171	func TestMergeSemanticV4Responses_FallbackCapAfterDedup(t *testing.T) {
172		t.Parallel()
173	
174		// Two cells return the same 20 ANN-only checkpoints (mirrored repo).
175		mk := func() []search.Result {
176			var rs []search.Result
177			for i := range mergedTier2Max + 5 {
178				rs = append(rs, v4Ckpt(
179					"c-"+string(rune('a'+i)), -1,
180					search.Meta{ANNScore: fptr(float64(i) / 100)},
181				))
182			}
183			return rs
184		}
185		resp, err := mergeSemanticV4Responses(context.Background(), 0, 0, []cellCallResult[*search.Response]{
186			v4CellOK(&search.Response{Results: mk(), Total: mergedTier2Max + 5}),
187			v4CellOK(&search.Response{Results: mk(), Total: mergedTier2Max + 5}),
188		})
189		if err != nil {
190			t.Fatal(err)
191		}
192		if len(resp.Results) != mergedTier2Max {
193			t.Errorf("fallback results = %d, want the full cap %d despite duplicates (dedup must run before the cap)", len(resp.Results), mergedTier2Max)
194		}
