197	// TestMergeSemanticV4Responses_FallbackDroppedWhenUpperTiersExist documents
198	// that a cell whose page is entirely tier-2 (its ANN fallback) contributes
199	// nothing when another cell produced tier 0/1 — matching how query-serve only
200	// shows the fallback tail when there is nothing better. Its Total must be
201	// excluded too: those matches are unreachable, so they must not be advertised.
202	func TestMergeSemanticV4Responses_FallbackDroppedWhenUpperTiersExist(t *testing.T) {
203		t.Parallel()
204	
205		upper := &search.Response{
