234	// TestMergeSemanticV4Responses_RepoOnlyPageCountsJustRepos covers a cell whose
235	// page mixes a repo hit with tier-2-only rows while another cell has tier 0/1:
236	// the tier-2 rows are dropped by the merge, so only the repo rows may count
237	// toward Total/Counts (trail finding 019f807e-60a3).
238	func TestMergeSemanticV4Responses_RepoOnlyPageCountsJustRepos(t *testing.T) {
239		t.Parallel()
240	
241		upper := &search.Response{
242			Results: []search.Result{v4Ckpt("good", 1, search.Meta{Score: 0.7})},
243			Total:   1,
244			Counts:  &search.TypeCounts{Checkpoints: 1},
