261		got := v4ResultIDs(t, resp.Results)
262		want := []string{"repo-1", "good"}
263		if strings.Join(got, ",") != strings.Join(want, ",") {
264			t.Errorf("results = %v, want %v (repo row merged, ann-only dropped)", got, want)
265		}
266		if resp.Total != 2 {
267			t.Errorf("total = %d, want 2 (1 upper + 1 repo row; the 49 dropped tier-2 matches are unreachable)", resp.Total)
268		}
269		if resp.Counts.Checkpoints != 1 || resp.Counts.Repos != 1 {
270			t.Errorf("counts = %+v, want checkpoints=1 repos=1", resp.Counts)
271		}
