276	// TestMergeSemanticV4Responses_DedupAdjustsTotalsAndCounts verifies a result
277	// mirrored across cells is kept once (first/higher-ranked wins) and that both
278	// the total and the per-type counts are reduced accordingly.
279	func TestMergeSemanticV4Responses_DedupAdjustsTotalsAndCounts(t *testing.T) {
280		t.Parallel()
281	
282		cellA := &search.Response{
283			Results: []search.Result{
284				v4Ckpt("dup", 1, search.Meta{Score: 0.9}),
285				v4Commit("sha1", 1, search.Meta{Score: 0.6}),
