404	// and the warning's denominator counts only cells that have the route.
405	func TestMergeSemanticV4Responses_UnavailableCellsSkippedQuietly(t *testing.T) {
406		t.Parallel()
407	
408		ok := &search.Response{Results: []search.Result{
409			v4Ckpt("ok", 1, search.Meta{Score: 0.5}),
410		}, Total: 1}
411	
412		resp, err := mergeSemanticV4Responses(context.Background(), 0, 0, []cellCallResult[*search.Response]{
413			v4CellErr(fmt.Errorf("cell gateway: %w", search.ErrCellUnavailable)),
414			v4CellErr(fmt.Errorf("resolving cell: %w", auth.ErrNoCellForJurisdiction)),
415			v4CellOK(ok),
