428		// cells that could actually serve (1 of 2, not 2 of 3).
429		resp, err = mergeSemanticV4Responses(context.Background(), 0, 0, []cellCallResult[*search.Response]{
430			v4CellErr(search.ErrCellUnavailable),
431			v4CellErr(errors.New("cell down")),
432			v4CellOK(ok),
433		})
434		if err != nil {
435			t.Fatal(err)
436		}
